	/**
	 * Resolusi {@link #getCalonSiswa()} menjadi objek {@link CalonSiswa} lewat cache aplikasi.
	 *
	 * <p>Dinamai {@code ambil...} (bukan {@code get...}) dengan sengaja: awalan {@code get} akan
	 * membuat Hibernate memperlakukannya sebagai properti dan mencoba memetakannya ke kolom. Pola
	 * penamaan ini konsisten di seluruh entity AIS.</p>
	 *
	 * <p>Mengembalikan {@code null} bila siswa tidak berasal dari PPDB ATAU bila barisnya sudah tidak
	 * ada &mdash; keduanya tidak dapat dibedakan pemanggil, karena tautannya memang bukan foreign key.</p>
	 *
	 * @return calon siswa asal, atau {@code null}
	 */
	public CalonSiswa ambilCalonSiswa() {
		return calonSiswa == null ? null : (CalonSiswa) ConstantValues.ambil(CalonSiswa.class.getName(), calonSiswa);
	}

