	/**
	 * Daftar id Facebook yang tertaut ke akun siswa ini.
	 *
	 * <p>Salah satu dari lima properti {@link SocialMediaCommonModel} yang dipakai jalur login
	 * sosial. Kolomnya menampung BANYAK id dipisah koma (satu siswa bisa menautkan beberapa
	 * akun); penambahannya lewat method {@code append...} yang bersangkutan.</p>
	 * <p><b>Getter yang menormalkan dan menulis balik.</b> Koma ganda dirapatkan (lima kali
	 * {@code replaceAll}), {@code null} dan nilai hampa {@code ","} diubah menjadi {@code ""},
	 * dan hasilnya ditulis ke field &mdash; karena property access, ikut tersimpan ke kolom
	 * pada flush berikutnya.</p>
	 *
	 * @return daftar id dipisah koma, atau {@code ""}; tidak pernah {@code null}
	 */
	public String getFacebookId() {
		if (facebookId != null && facebookId.contains(",,")) {
			for (int i = 0; i < 5; i++) {
				facebookId = facebookId.replaceAll(",,", ",");
			}
		}
		if (facebookId == null) {
			facebookId = "";
		}
		if (facebookId.trim().equals(",")) {
			facebookId = "";
		}
		return facebookId;
	}

	/**
	 * Setel daftar id Facebook (menimpa seluruh daftar).
	 *
	 * @param facebookId daftar id dipisah koma; boleh {@code null}
	 */
	public void setFacebookId(String facebookId) {
		this.facebookId = facebookId;
	}

	/**
	 * Tambahkan satu id Facebook ke daftar tautan akun siswa.
	 *
	 * <p><b>Tanpa pemeriksaan duplikat dan tanpa validasi</b> &mdash; berbeda dari
	 * {@link #appendEmail(String)} yang setidaknya memeriksa keberadaan dan format. Memanggil dua kali
	 * dengan id yang sama menghasilkan entri kembar; argumen {@code null} menghasilkan literal
	 * {@code "null"} di dalam daftar.</p>
	 *
	 * @param facebookId id yang ditambahkan
	 */
	public void appendFacebookId(String facebookId) {
		this.facebookId = this.facebookId == null || this.facebookId.trim().isEmpty() ? facebookId
				: this.facebookId + "," + facebookId;
	}

