	/**
	 * Jenis kelamin siswa dalam bentuk panjang ({@code "Laki-laki"}/{@code "Perempuan"}) &mdash;
	 * <b>getter yang MENORMALKAN dan menulis balik</b>.
	 *
	 * <p>Getter menerima beragam bentuk masukan historis dan menyeragamkannya ke field:</p>
	 * <ul>
	 *   <li>{@code "L"} (abaikan besar-kecil) atau {@code "Laki-Laki"} &rarr; {@code "Laki-laki"};</li>
	 *   <li>{@code "P"} &rarr; {@code "Perempuan"};</li>
	 *   <li>{@code null} &rarr; {@code ""};</li>
	 *   <li>selanjutnya, teks apa pun yang MENGANDUNG {@code "laki"} &rarr; {@code "Laki-laki"}, dan
	 *   yang mengandung {@code "puan"} &rarr; {@code "Perempuan"}.</li>
	 * </ul>
	 * <p>Karena property access, hasil normalisasi ikut ditulis ke kolom {@code jenis_kelamin}.
	 * Konsekuensi yang perlu diingat: nilai {@code "L"}/{@code "P"} gaya lama TIDAK dapat dipulihkan
	 * setelah baris pernah dibaca, dan siswa yang jenis kelaminnya belum diisi akan menerima
	 * {@code ""} secara permanen &mdash; sehingga penyaring {@code jenis_kelamin IS NULL} berhenti
	 * menemukan mereka. Cabang terakhir juga bersifat "mengandung", jadi teks bebas yang kebetulan
	 * memuat potongan itu ikut dikonversi.</p>
	 *
	 * <p>Filter jenis kelamin pada layar daftar siswa membandingkan dengan nilai panjang, jadi baris
	 * yang belum pernah ternormalkan tidak akan cocok dengan filter mana pun.</p>
	 *
	 * @return {@code "Laki-laki"}, {@code "Perempuan"}, atau {@code ""}
	 */
	@Column(name = "jenis_kelamin", nullable = false, length = 9)
	public String getJenisKelamin() {

		if (jenisKelamin != null
				&& (jenisKelamin.trim().equalsIgnoreCase("L") || jenisKelamin.trim().equals("Laki-Laki"))) {
			jenisKelamin = "Laki-laki";
		} else if (jenisKelamin != null && jenisKelamin.trim().equalsIgnoreCase("P")) {
			jenisKelamin = "Perempuan";
		} else if (jenisKelamin == null) {
			jenisKelamin = "";
		}

		if (jenisKelamin.toLowerCase().contains("laki")) {
			jenisKelamin = "Laki-laki";
		} else if (jenisKelamin.toLowerCase().contains("puan")) {
			jenisKelamin = "Perempuan";
		}

		return this.jenisKelamin;
	}

	/**
	 * Setel jenis kelamin siswa (bentuk apa pun; dinormalkan saat dibaca).
	 *
	 * @param jenisKelamin jenis kelamin; boleh {@code null}
	 */
	public void setJenisKelamin(String jenisKelamin) {
		this.jenisKelamin = jenisKelamin;
	}

