	/**
	 * Status siswa dalam keluarga ({@code "Anak Kandung"}, {@code "Anak Angkat"}, dan seterusnya).
	 *
	 * <p>Nilai bawaan {@code "Anak Kandung"} dikembalikan bila kolom kosong dan, karena property
	 * access, ikut tersimpan pada flush berikutnya.</p>
	 *
	 * <p><b>Perhatian panjang kolom.</b> Kolomnya {@code varchar(12)} sedangkan nilai bawaannya
	 * sendiri sudah 12 karakter &mdash; tidak ada ruang untuk label yang lebih panjang. Setternya
	 * karena itu memotong paksa (lihat {@link #setStatusDalamKeluarga(String)}).</p>
	 *
	 * @return status dalam keluarga; tidak pernah {@code null}
	 */
	@Column(name = "status_dalam_keluarga", length = 12)
	public String getStatusDalamKeluarga() {
		return this.statusDalamKeluarga == null || statusDalamKeluarga.trim().isEmpty() ? "Anak Kandung"
				: statusDalamKeluarga;
	}

	/**
	 * Setel status siswa dalam keluarga, dengan pemotongan paksa ke 12 karakter.
	 *
	 * <p>Jaring pengaman yang sengaja dipasang: kolom {@code varchar(12)} akan menggagalkan seluruh
	 * {@code UPDATE} dengan {@code PSQLException "value too long"} bila ada pemanggil mengirim teks
	 * lebih panjang. Konsekuensinya label panjang tersimpan TERPOTONG diam-diam, bukan ditolak.</p>
	 *
	 * @param statusDalamKeluarga status; boleh {@code null}
	 */
	public void setStatusDalamKeluarga(String statusDalamKeluarga) {
		// Jaring pengaman: kolom DB dibatasi varchar(12) -- potong agar tidak pernah menggagalkan
		// update dgn PSQLException "value too long" bila ada caller lain mengirim teks lebih panjang.
		this.statusDalamKeluarga = statusDalamKeluarga != null && statusDalamKeluarga.length() > 12
				? statusDalamKeluarga.substring(0, 12) : statusDalamKeluarga;
	}

	/**
	 * Tahun masuk siswa, dengan TAHUN BERJALAN sebagai nilai bawaan.
	 *
	 * <p>Kolom {@code nullable = false}. Bila kosong, getter mengembalikan tahun kalender saat ini,
	 * dan karena property access nilai itu tersimpan permanen &mdash; sehingga siswa lama yang tahun
	 * masuknya belum terisi akan dicap sebagai angkatan tahun ini, tergantung kapan barisnya kebetulan
	 * pertama kali dibaca.</p>
	 *
	 * <p>Dipakai {@link #ambilKelas(Siswa, String)} sebagai penyaring: kelas dari tahun ajaran yang
	 * lebih awal dari tahun masuk diabaikan. Cap angkatan yang salah karena itu juga dapat
	 * menyembunyikan kelas siswa.</p>
	 *
	 * @return tahun masuk; tidak pernah {@code null}
	 */
	@Column(name = "tahun_masuk", nullable = false)
	public Integer getTahunMasuk() {
		return this.tahunMasuk == null ? ais.ui.util.WaktuUtil.getCalendar().get(Calendar.YEAR) : this.tahunMasuk;
	}

