	/**
	 * Telepon orang tua &mdash; <b>getter DESTRUKTIF: selalu ditimpa dengan {@link #getHp1ayah()}</b>.
	 *
	 * <p>Kembar persis pola {@link #getAlamatOrangTua()}: baris pertama menugaskan
	 * {@code teleponOrangTua = getHp1ayah()} tanpa syarat, dan kolom {@code telepon_orang_tua}
	 * dipetakan dapat ditulis. Karena {@link #getHp1ayah()} sendiri mengembalikan {@code ""} bila
	 * kosong, membaca baris siswa yang HP ayahnya belum diisi akan MENGOSONGKAN nomor telepon orang
	 * tua yang tersimpan &mdash; permanen, dan tanpa jejak selain revisi Envers.</p>
	 *
	 * <p>Getter ini dipanggil dari banyak tempat panas: renderer grid lewat
	 * {@link #tampilkanHp(Component)}, pengumpulan nomor {@link #ambilTelp()}, dan filter pencarian
	 * telepon pada layar daftar. Praktis setiap kali daftar siswa dibuka, kolom ini ditulis ulang
	 * untuk seluruh baris yang tampil.</p>
	 *
	 * @return nomor HP ayah setelah karakter non-angka dibuang; tidak pernah {@code null}
	 */
	@Column(name = "telepon_orang_tua")
	public String getTeleponOrangTua() {
		teleponOrangTua = getHp1ayah();
		return this.teleponOrangTua == null ? "" : teleponOrangTua.trim().replaceAll("[^\\d.]", "");
	}

