	/**
	 * NISN (Nomor Induk Siswa Nasional) &mdash; <b>getter yang menyalin NIS ke kolom NISN bila
	 * kosong</b>.
	 *
	 * <p>Bila kolom {@code nomor_induk_nasional} kosong, getter menugaskan
	 * {@code nomorIndukNasional = getNomorInduk()} dan mengembalikannya; karena property access,
	 * salinan itu tersimpan pada flush berikutnya.</p>
	 *
	 * <p><b>Dua konsekuensi penting.</b> (1) Kolom ini dipetakan {@code unique = true}, sedangkan
	 * {@link #getNomorInduk()} TIDAK unik &mdash; pada instalasi multi-sekolah, dua siswa dari sekolah
	 * berbeda yang kebetulan bernomor induk sama akan menabrak unique constraint begitu keduanya
	 * dibaca, dan kegagalannya muncul sebagai flush yang gagal di tempat yang sama sekali tidak
	 * berhubungan. (2) NISN palsu hasil salinan itu menjadi nama pengguna login siswa DAN sumber kata
	 * sandi bawaan pada {@link #getPass()} &mdash; keduanya karena itu ikut berubah tanpa ada yang
	 * mengubahnya secara sadar.</p>
	 *
	 * <p>Alias baca-sajanya {@link #getNim()}.</p>
	 *
	 * @return NISN (mungkin baru disalin dari NIS), atau {@code ""}; tidak pernah {@code null}
	 */
	@Column(name = "nomor_induk_nasional", unique = true)
	public String getNomorIndukNasional() {
		if (nomorIndukNasional == null || nomorIndukNasional.trim().isEmpty()) {
			nomorIndukNasional = getNomorInduk();
		}
		return this.nomorIndukNasional == null || this.nomorIndukNasional.trim().isEmpty() ? ""
				: nomorIndukNasional.trim();
	}

	/**
	 * Setel NISN siswa.
	 *
	 * @param nomorIndukNasional NISN; boleh {@code null} (akan disalin dari NIS saat dibaca)
	 */
	public void setNomorIndukNasional(String nomorIndukNasional) {
		this.nomorIndukNasional = nomorIndukNasional;
	}

	/**
	 * Setel kata sandi siswa (nilai TERENKRIPSI, bukan teks polos).
	 *
	 * <p>Pemanggil wajib mengirim hasil {@code Common.desEncrypter.get().encrypt(...)}: jalur
	 * verifikasi login membandingkan CIPHERTEXT dengan ciphertext (lihat {@code FilterLoginAis}),
	 * sehingga menyimpan teks polos di sini membuat siswa tidak pernah bisa login.</p>
	 *
	 * @param pass kata sandi yang sudah dienkripsi DES; boleh {@code null}
	 * @see #getPass()
	 */
	public void setPass(String pass) {
		this.pass = pass;
	}

	/**
	 * Kata sandi portal siswa dalam bentuk terenkripsi &mdash; <b>getter yang MEMBUAT kata sandi bila
	 * belum ada</b>.
	 *
	 * <p>Bila kolom {@code pass} masih kosong sementara {@link #getNomorIndukNasional()} terisi,
	 * getter ini <i>membangkitkan</i> kata sandi baru = {@code DES(NISN)} dan menyetel
	 * {@link #getIs_encripted()} menjadi {@code true}. Karena entity memakai property access dan
	 * {@code dynamicUpdate}, nilai itu ikut tertulis ke basis data pada flush berikutnya. Jadi sekadar
	 * MEMBACA baris siswa &mdash; termasuk lewat layar daftar, laporan, atau endpoint REST &mdash;
	 * sudah cukup untuk memberi siswa itu kata sandi permanen tanpa ada yang menekan tombol apa pun.</p>
	 *
	 * <p><b>PERINGATAN KEAMANAN.</b> Kata sandi bawaan yang terbentuk dengan cara ini SAMA DENGAN NISN
	 * siswa sendiri:</p>
	 * <ul>
	 *   <li>{@code UserDetailsServiceImpl}/{@code CommonSecurityLoginHelper} mendekripsi kolom ini
	 *   kembali menjadi teks polos ({@code decrypt(siswa.getPass())}), dan nama pengguna login siswa
	 *   adalah NISN/nomor induk itu sendiri &mdash; jadi pasangan kredensial bawaannya
	 *   {@code (NISN, NISN)};</li>
	 *   <li>NISN bukan rahasia: tercetak di kartu pelajar, DAN dapat dipanen anonim lewat endpoint
	 *   REST {@code /resources/pos/siswa/{nama}/{mulai}/{banyak}} yang tidak memeriksa kredensial sama
	 *   sekali;</li>
	 *   <li>enkripsinya DES dengan passphrase tetap yang tertanam di kode dan sama untuk semua
	 *   instalasi, sehingga nilai kolom ini bukan pelindung apa pun bagi siapa yang bisa membaca basis
	 *   data atau cadangannya (lihat {@code ais.common.Common#DES_PASS_PHRASE}).</li>
	 * </ul>
	 * <p>{@link #getUbahPasword()} yang bernilai {@code null} menandai siswa yang tidak pernah
	 * mengganti kata sandi bawaan itu. Perilaku kode TIDAK diubah di sini; ini catatan dokumentasi.</p>
	 *
	 * @return kata sandi terenkripsi (dibangkitkan bila belum ada), atau {@code null} bila NISN juga
	 *         kosong
	 * @see #urlLogin()
	 */
	@Column(name = "pass", nullable = true, length = 100)
	public String getPass() {
		if ((pass == null || pass.trim().isEmpty()) && getNomorIndukNasional() != null
				&& !getNomorIndukNasional().trim().isEmpty()) {
			pass = Common.desEncrypter.get().encrypt(getNomorIndukNasional().trim());
			is_encripted = true;
		}
		return pass;
	}

