	/**
	 * Tahun kelulusan siswa &mdash; <b>getter DESTRUKTIF: mengembalikan {@code null} bila status
	 * keluar belum diisi</b>.
	 *
	 * <p>Dua syarat membuat method ini mengembalikan {@code null} walaupun kolomnya berisi angka:
	 * (1) {@link #getStatusKeluar()} masih {@code null}, atau (2) tahun di luar rentang 1900&ndash;2900.
	 * Karena entity memakai property access, {@code null} itulah yang ditulis Hibernate ke kolom pada
	 * flush berikutnya &mdash; jadi membaca baris siswa yang tahun lulusnya sudah diisi tetapi status
	 * keluarnya belum dipilih akan MENGHAPUS tahun lulus tersebut secara permanen. Urutan pengisian
	 * formulir (tahun lulus dulu, status keluar belakangan) karena itu tidak aman.</p>
	 *
	 * <p>Perhatikan asimetri dengan {@link #getTanggalLulus()}, yang mengembalikan tanggalnya apa
	 * adanya tanpa syarat status keluar &mdash; sesudah kejadian di atas, sebuah baris dapat memiliki
	 * tanggal lulus tetapi tanpa tahun lulus.</p>
	 *
	 * @return tahun kelulusan, atau {@code null} bila status keluar belum diisi/tahun tidak masuk akal
	 */
	public Integer getTahunLulus() {
		if (getStatusKeluar() == null || (tahunLulus != null && (tahunLulus < 1900 || tahunLulus > 2900))) {
			return null;
		}
		return tahunLulus;
	}

	/**
	 * Setel tahun kelulusan siswa.
	 *
	 * @param tahunLulus tahun lulus; boleh {@code null}
	 */
	public void setTahunLulus(Integer tahunLulus) {
		this.tahunLulus = tahunLulus;
	}

	/**
	 * Gelombang pendaftaran PSB siswa, dengan data pendaftaran sebagai CADANGAN (bukan penimpa).
	 *
	 * <p>Bila kolom {@code current_gelombang_pendaftaran_psb_id} masih kosong dan
	 * {@link #getCalonSiswa()} terisi, nilainya diambil dari {@link CalonSiswa}. Komentar di kode
	 * menegaskan bahwa ini sengaja cadangan, bukan override, supaya admin dapat memindahkan siswa
	 * antar gelombang tanpa nilainya dikembalikan setiap kali dibaca.</p>
	 *
	 * <p><b>Efeknya tetap denormalisasi permanen.</b> Nilai cadangan ditulis ke field, sehingga sekali
	 * dibaca pada instance terhubung sesi, gelombang PPDB tersalin ke baris siswa dan tidak lagi
	 * mengikuti perubahan di sisi PPDB. Kegagalan resolusi {@link CalonSiswa} ditelan dan dicatat ke
	 * audit &mdash; gejalanya kolom yang tetap kosong tanpa pesan galat.</p>
	 *
	 * @return gelombang PSB siswa, atau {@code null}
	 */
	@ManyToOne(cascade = { CascadeType.PERSIST, CascadeType.MERGE }, fetch = FetchType.LAZY)
	@JoinColumn(name = "current_gelombang_pendaftaran_psb_id")
	public GelombangPendaftaranPsb getGelombangPendaftaranPsb() {
		gelombangPendaftaranPsb = check(gelombangPendaftaranPsb);

		// Gunakan gelombang CalonSiswa sebagai FALLBACK (bukan override) — pola sama
		// dengan getPenjurusanSekolah: hanya dipakai jika Siswa belum punya nilai sendiri.
		if (gelombangPendaftaranPsb == null && getCalonSiswa() != null) {

			try {
				CalonSiswa calonSiswa = (CalonSiswa) ConstantValues.ambil(CalonSiswa.class.getName(), getCalonSiswa());
				if (calonSiswa != null && calonSiswa.getGelombangPendaftaranPsb() != null) {
					gelombangPendaftaranPsb = calonSiswa.getGelombangPendaftaranPsb();
				}
			} catch (Exception e) { ais.common.ErrorAuditUtil.record(e, "auto-audit(empty-catch) src/ais/database/model/sekolah/Siswa.java:1479");
			}

		}

		return this.gelombangPendaftaranPsb;
	}

	/**
	 * Setel gelombang pendaftaran PSB siswa.
	 *
	 * @param gelombangPendaftaranPsb gelombang PSB; boleh {@code null}
	 */
	public void setGelombangPendaftaranPsb(GelombangPendaftaranPsb gelombangPendaftaranPsb) {
		this.gelombangPendaftaranPsb = gelombangPendaftaranPsb;
	}

	/**
	 * Jurusan/peminatan siswa, dengan penjurusan pendaftaran PSB sebagai CADANGAN bersyarat.
	 *
	 * <p>Cadangan dari {@link CalonSiswa#ambilPenjurusanSekolah()} hanya dipakai bila (a) kolom
	 * {@code penjurusan_sekolah_id} masih kosong, (b) sekolahnya menyalakan
	 * {@code Sekolah.penjurusanWajibDipilih}, dan (c) siswa berasal dari PPDB. Sama seperti
	 * {@link #getGelombangPendaftaranPsb()}, nilai cadangan itu ditulis ke field sehingga menjadi
	 * permanen begitu dibaca sekali.</p>
	 *
	 * <p><b>Getter dibungkus {@code try}/{@code catch} penuh dengan sengaja.</b> Komentar di kode
	 * mencatat pernah terjadi {@code NullPointerException} tak tertangkap (proxy
	 * {@link Sekolah}/{@link CalonSiswa} yang sudah <i>detached</i>) yang menjatuhkan seluruh halaman
	 * pemanggil hanya karena membaca jurusan. Sekarang kegagalan dicatat ke audit dan getter
	 * mengembalikan field mentah apa adanya. Konsekuensinya kegagalan bersifat SENYAP: bila jurusan
	 * tampak hilang di layar, periksa audit galat, bukan data.</p>
	 *
	 * <p>{@link PenjurusanSekolah} juga dimensi tarif keuangan lewat {@code PengaturanBiaya}, sehingga
	 * perubahan nilai di sini dapat mengubah nominal tagihan siswa.</p>
	 *
	 * @return jurusan siswa, cadangan dari pendaftaran, atau {@code null}
	 */
	@ManyToOne(cascade = { CascadeType.PERSIST, CascadeType.MERGE }, fetch = FetchType.LAZY)
	@JoinColumn(name = "penjurusan_sekolah_id", nullable = true)
	public PenjurusanSekolah getPenjurusanSekolah() {
		// Getter dibungkus try-catch penuh: sempat NPE tak tertangkap (mis. proxy
		// Sekolah/CalonSiswa detached saat resolusi lazy) yang menjatuhkan seluruh
		// form/halaman pemanggil (mis. SiswaAction) hanya gara-gara membaca jurusan.
		// Root cause pastinya tak bisa dipastikan tanpa reproduksi live, jadi getter
		// digagalkan dengan aman (kembalikan field mentah) alih-alih meledak.
		try {
			penjurusanSekolah = check(penjurusanSekolah);

			// Gunakan penjurusan CalonSiswa sebagai FALLBACK (bukan override) — hanya jika
			// Siswa belum punya penjurusan sendiri. Ini memungkinkan admin mengubah jurusan
			// siswa (pindah jurusan) tanpa dikembalikan ke nilai PPDB setiap kali dibaca.
			Sekolah sekolahData = getSekolah();
			Boolean penjurusanWajibDipilih = sekolahData == null ? null : sekolahData.getPenjurusanWajibDipilih();
			if (penjurusanSekolah == null && Boolean.TRUE.equals(penjurusanWajibDipilih) && getCalonSiswa() != null) {

				try {
					CalonSiswa calonSiswa = (CalonSiswa) ConstantValues.ambil(CalonSiswa.class.getName(), getCalonSiswa());
					if (calonSiswa != null && calonSiswa.ambilPenjurusanSekolah() != null) {
						penjurusanSekolah = calonSiswa.ambilPenjurusanSekolah();
					}
				} catch (Exception e) { ais.common.ErrorAuditUtil.record(e, "auto-audit(empty-catch) src/ais/database/model/sekolah/Siswa.java:1504");
				}

			}
		} catch (Exception e) {
			ais.common.ErrorAuditUtil.record(e, "auto-audit src/ais/database/model/sekolah/Siswa.java:getPenjurusanSekolah");
		}

		return penjurusanSekolah;
	}

