	/**
	 * Ambil daftar materi pertemuan untuk pengguna yang SEDANG LOGIN &mdash; implementasi
	 * {@link VOMahasiswaDosen#ambilMateri(TreeMap, boolean, Label)}.
	 *
	 * <p><b>Perhatikan: parameter siswa diabaikan.</b> Method ini tidak memakai {@code this} sama
	 * sekali; ia memungut {@code Common.getCurrentUser()} lalu mendelegasikan ke
	 * {@link PertemuanFileContent#ambilMateri}. Jadi memanggilnya pada objek siswa A saat yang login
	 * siswa B akan mengembalikan materi milik B. Perilaku ini kebetulan aman dari sisi kebocoran data
	 * (hasilnya selalu milik pengguna sendiri), tetapi menyesatkan bila dipakai pada alur batch/
	 * laporan yang mengharapkan materi milik siswa pada argumen.</p>
	 *
	 * @param pertemuans peta pertemuan yang materinya diminta
	 * @param refresh    {@code true} memaksa pembacaan ulang, mengabaikan cache berkas
	 * @param label      label ZK yang diperbarui sebagai indikator progres; boleh {@code null}
	 * @return peta materi milik pengguna yang sedang login
	 */
	@Override
	public TreeMap<String, Object[]> ambilMateri(TreeMap<String, Long> pertemuans, boolean refresh, Label label) {
		Tbmuser tbmuser = Common.getCurrentUser();
		return PertemuanFileContent.ambilMateri(pertemuans, refresh, label, tbmuser);
	}

