	/**
	 * Kecamatan alamat rumah siswa (relasi ke {@link Wilayah}) &mdash; <b>getter yang mengganti
	 * referensi wilayah yatim</b>.
	 *
	 * <p>Selain resolusi {@code check()} biasa, getter ini memeriksa apakah wilayah yang tertaut tidak
	 * punya induk ({@code getWilayahInduk() == null}). Bila ya, ia menelusuri seluruh cache
	 * {@link Wilayah} mencari baris ber-kode Feeder SAMA yang punya induk, lalu menggantikannya.</p>
	 *
	 * <p><b>Konsekuensi.</b> (1) Karena property access, penggantian itu ikut tertulis ke kolom
	 * {@code kecamatan} pada flush berikutnya &mdash; membaca alamat siswa dapat mengubah FK
	 * wilayahnya. (2) Bila ada lebih dari satu kandidat ber-kode Feeder sama, yang terpilih adalah
	 * yang pertama ditemui pada iterasi cache, yaitu urutan yang tidak dijamin stabil antar restart.
	 * (3) Penelusuran linear atas seluruh tabel wilayah dijalankan pada SETIAP pembacaan yang
	 * wilayahnya masih yatim.</p>
	 *
	 * @return kecamatan (mungkin sudah digantikan duplikat yang sehat), atau {@code null}
	 */
	@ManyToOne(cascade = { CascadeType.PERSIST, CascadeType.MERGE }, fetch = FetchType.LAZY)
	@JoinColumn(name = "kecamatan", nullable = true)
	public Wilayah getKecamatan() {
		kecamatan = check(kecamatan);

		if (kecamatan != null && kecamatan.getWilayahInduk() == null) {

			for (Object o : ConstantValues.ambilBerdasarClass(Wilayah.class).values()) {
				Wilayah w = (Wilayah) o;
				if (w != null && w.getFeeder() != null && kecamatan.getFeeder() != null
						&& kecamatan.getFeeder().equals(w.getFeeder()) && w.getWilayahInduk() != null) {
					kecamatan = w;
					break;
				}
			}

		}

		return kecamatan;
	}

	/**
	 * Setel kecamatan alamat rumah siswa.
	 *
	 * @param kecamatan wilayah tingkat kecamatan; boleh {@code null}
	 */
	public void setKecamatan(Wilayah kecamatan) {
		this.kecamatan = kecamatan;
	}

