	/**
	 * Bangun ulang berkas indeks angket dari basis data.
	 *
	 * <p>Urutannya: query seluruh id {@link ChecklistBaruPenilaianGuruOlehSiswa} milik siswa ini,
	 * hapus berkas lama, tulis JSON kosong, lalu daftarkan id satu per satu lewat
	 * {@link #populateChecklistBaruPenilaianGuruOlehSiswa(Long)}. Karena setiap pemanggilan
	 * {@code populate...} membaca-lalu-menulis berkas secara utuh, biaya operasi ini kuadratik
	 * terhadap jumlah angket &mdash; N pembacaan + N penulisan berkas untuk N baris.</p>
	 *
	 * <p>Tidak ada penguncian: dua thread yang menyegarkan siswa yang sama bisa saling menimpa
	 * indeks (lihat catatan "bukan penguncian antar-thread" pada
	 * {@link ais.database.model.GeneralValueObject#udah(String)}).</p>
	 *
	 * @param session sesi Hibernate yang dipakai untuk query id; harus aktif
	 */
	@SuppressWarnings("unchecked")
	public void reInitChecklistBaruPenilaianGuruOlehSiswa(Session session) {
		List<Long> checklistBaruPenilaianGuruOlehSiswas = session
				.createCriteria(ChecklistBaruPenilaianGuruOlehSiswa.class).addOrder(Order.asc("id"))
				.setProjection(Projections.property("id")).add(Restrictions.eq("siswa", this)).list();
		bersihkanLokasiChecklistBaruPenilaianGuruOlehSiswa();
		tulisLokasiChecklistBaruPenilaianGuruOlehSiswa(new JSONObject().toString());
		for (Long checklistBaruPenilaianGuruOlehSiswaid : checklistBaruPenilaianGuruOlehSiswas) {
			populateChecklistBaruPenilaianGuruOlehSiswa(checklistBaruPenilaianGuruOlehSiswaid);
		}
		checklistBaruPenilaianGuruOlehSiswas = null;
	}

	/**
	 * Tandai satu angket sebagai tidak lagi tercatat pada indeks siswa ini.
	 *
	 * <p>Implementasinya menulis nilai KOSONG untuk kunci tersebut, bukan membuang kuncinya. Kunci
	 * itu tetap ada di berkas selamanya; hanya pembacaan
	 * {@link #ambilChecklistBaruPenilaianGuruOlehSiswa(Session, boolean)} yang melewatinya karena
	 * menyaring nilai kosong. Berkas indeks karena itu tumbuh monoton dan tidak pernah menyusut.</p>
	 *
	 * @param id id angket yang dilepas dari indeks
	 */
	public void removeChecklistBaruPenilaianGuruOlehSiswa(Serializable id) {
		try {
			JSONObject c = new JSONObject(ambilLokasiChecklistBaruPenilaianGuruOlehSiswa());
			c.put(id.toString(), "");
			tulisLokasiChecklistBaruPenilaianGuruOlehSiswa(c.toString());
		} catch (Exception e) { ais.common.ErrorAuditUtil.record(e, "auto-audit(empty-catch) src/ais/database/model/sekolah/Siswa.java:2100");

		}
	}

	/**
	 * Daftarkan satu id angket ke berkas indeks siswa ini.
	 *
	 * <p>Baca berkas &rarr; sisipkan pasangan {@code "<id>" : "<id>"} &rarr; tulis ulang seluruh
	 * berkas. Argumen {@code null} diabaikan diam-diam; kegagalan JSON/I/O ditelan dan dicatat ke
	 * audit.</p>
	 *
	 * @param checklistBaruPenilaianGuruOlehSiswa id angket yang didaftarkan; {@code null} = no-op
	 */
	public void populateChecklistBaruPenilaianGuruOlehSiswa(Long checklistBaruPenilaianGuruOlehSiswa) {
		try {
			if (checklistBaruPenilaianGuruOlehSiswa == null) {
				return;
			}
			JSONObject c = new JSONObject(ambilLokasiChecklistBaruPenilaianGuruOlehSiswa());
			c.put(checklistBaruPenilaianGuruOlehSiswa.toString(), checklistBaruPenilaianGuruOlehSiswa.toString());
			tulisLokasiChecklistBaruPenilaianGuruOlehSiswa(c.toString());
		} catch (Exception e) { ais.common.ErrorAuditUtil.record(e, "auto-audit(empty-catch) src/ais/database/model/sekolah/Siswa.java:2113");
		}
	}

	/**
	 * Ambil seluruh angket penilaian guru oleh siswa ini, dipetakan dengan kunci
	 * {@code "<idGuru>-<idJadwalPelajaran>"}.
	 *
	 * <p>Alurnya: bila {@code refresh} atau penanda
	 * {@link ais.database.model.GeneralValueObject#udah(String)} belum terpasang, indeks dibangun
	 * ulang dulu; lalu id-id dari berkas indeks dipakai memuat baris sesungguhnya lewat
	 * {@code ambilDataBanyak}. Baris yang jadwal pelajaran atau gurunya {@code null} DIBUANG diam-diam
	 * &mdash; angket yatim tidak pernah muncul di layar maupun rekap.</p>
	 *
	 * <p><b>Kunci bisa bertabrakan.</b> Peta di-key hanya oleh (guru, jadwal); bila seorang siswa
	 * mengisi angket yang sama lebih dari sekali (tidak ada unique constraint yang mencegahnya),
	 * entri terakhir menang dan yang lain hilang dari hasil.</p>
	 *
	 * @param session sesi Hibernate aktif
	 * @param refresh {@code true} memaksa indeks dibangun ulang dari basis data
	 * @return peta angket ber-kunci {@code guruId-jadwalId}; kosong (bukan {@code null}) bila tidak ada
	 */
	@SuppressWarnings("unchecked")
	public Map<String, ChecklistBaruPenilaianGuruOlehSiswa> ambilChecklistBaruPenilaianGuruOlehSiswa(Session session,
			boolean refresh) {
		if (refresh || !udah("ChecklistBaruPenilaianGuruOlehSiswa")) {
			reInitChecklistBaruPenilaianGuruOlehSiswa(session);
		}
		List<String> keysAmbil = new ArrayList<String>();
		try {
			JSONObject c = new JSONObject(ambilLokasiChecklistBaruPenilaianGuruOlehSiswa());
			Iterator<String> keys = c.keys();
			while (keys.hasNext()) {
				String key = keys.next();
				try {
					String s = c.getString(key);
					if (!s.trim().isEmpty()) {
						keysAmbil.add(key);
					}
				} catch (Exception e) {
					e.printStackTrace(); ais.common.ErrorAuditUtil.record(e, "auto-audit src/ais/database/model/sekolah/Siswa.java:2135");
				}
			}
		} catch (Exception e) { ais.common.ErrorAuditUtil.record(e, "auto-audit(empty-catch) src/ais/database/model/sekolah/Siswa.java:2138");
//			e.printStackTrace();
		}

		Map<String, ChecklistBaruPenilaianGuruOlehSiswa> maps = new HashMap<String, ChecklistBaruPenilaianGuruOlehSiswa>();
		List<ChecklistBaruPenilaianGuruOlehSiswa> dataDiambil = ChecklistBaruPenilaianGuruOlehSiswa
				.ambilDataBanyak(ChecklistBaruPenilaianGuruOlehSiswa.class, keysAmbil);
		for (ChecklistBaruPenilaianGuruOlehSiswa checklistBaruPenilaianGuruOlehSiswa : dataDiambil) {
			if (checklistBaruPenilaianGuruOlehSiswa != null
					&& checklistBaruPenilaianGuruOlehSiswa.getJadwalPelajaran() != null
					&& checklistBaruPenilaianGuruOlehSiswa.getGuru() != null) {
				String mykey = checklistBaruPenilaianGuruOlehSiswa.getGuru().getId() + "-"
						+ checklistBaruPenilaianGuruOlehSiswa.getJadwalPelajaran().getId();
				maps.put(mykey, checklistBaruPenilaianGuruOlehSiswa);
			}
		}
		dataDiambil = null;
		return maps;
	}

	/**
	 * Varian {@link #ambilChecklistBaruPenilaianGuruOlehSiswa(Session, boolean)} dengan kunci yang
	 * juga menyertakan id siswa: {@code "<idSiswa>_<idJadwal>_<idGuru>"}.
	 *
	 * <p>Dipakai layar yang menggabungkan angket banyak siswa dalam satu peta, sehingga kunci
	 * (guru, jadwal) saja tidak cukup unik. Perhatikan pembalikan urutan komponen kunci dibanding
	 * method sumbernya (di sana {@code guru-jadwal}, di sini {@code siswa_jadwal_guru}) &mdash; kedua
	 * format kunci TIDAK dapat dipertukarkan.</p>
	 *
	 * <p>Tidak ada penjagaan {@code null} pada {@code getSiswa()}: baris angket yang siswanya kosong
	 * akan melempar {@code NullPointerException} di sini, sementara method sumbernya justru sudah
	 * membuang baris tanpa guru/jadwal.</p>
	 *
	 * @param session sesi Hibernate aktif
	 * @param refresh {@code true} memaksa indeks dibangun ulang dari basis data
	 * @return peta angket ber-kunci {@code siswaId_jadwalId_guruId}
	 */
	public Map<String, ChecklistBaruPenilaianGuruOlehSiswa> byKey(Session session, boolean refresh) {
		Map<String, ChecklistBaruPenilaianGuruOlehSiswa> maps = ambilChecklistBaruPenilaianGuruOlehSiswa(session,
				refresh);
		Map<String, ChecklistBaruPenilaianGuruOlehSiswa> mapsKey = new HashMap<String, ChecklistBaruPenilaianGuruOlehSiswa>();
		for (ChecklistBaruPenilaianGuruOlehSiswa checklistBaruPenilaianGuruOlehSiswa : maps.values()) {
			Siswa siswa = checklistBaruPenilaianGuruOlehSiswa.getSiswa();
			JadwalPelajaran jadwalPelajaran = checklistBaruPenilaianGuruOlehSiswa.getJadwalPelajaran();
			Guru guru = checklistBaruPenilaianGuruOlehSiswa.getGuru();
			String kodeUnik = siswa.getId() + "_" + jadwalPelajaran.getId() + "_" + guru.getId();
			mapsKey.put(kodeUnik, checklistBaruPenilaianGuruOlehSiswa);
		}
		maps = null;
		return mapsKey;
	}

	/**
	 * Id sidik jari mesin absensi untuk siswa ini.
	 *
	 * <p>Nilai disimpan GANDA: kolom basis data dan berkas cermin di disk lewat
	 * {@link ais.database.model.GeneralValueObject#put(String, String)}/
	 * {@link ais.database.model.GeneralValueObject#retreive(String)}. Getter ini memprioritaskan
	 * kolom; hanya bila kolom kosong, nilai diambil dari berkas cermin. Selama startup aplikasi
	 * {@code retreive} sengaja mengembalikan {@code ""} tanpa menyentuh disk (lihat penjelasan
	 * "penjaga startup" di kelas induk), jadi pembacaan pada fase itu bisa mengembalikan
	 * {@code null}/kosong walaupun berkasnya ada.</p>
	 *
	 * @return id sidik jari sudah di-{@code trim}, atau {@code null} bila tidak ada di kolom maupun berkas
	 */
	public String getIdfinger() {
		String s = idfinger == null || idfinger.trim().isEmpty() ? retreive("idfinger") : idfinger;
		return s == null ? null : s.trim();
	}

	/**
	 * Setel id sidik jari sekaligus menulis berkas cermin di disk.
	 *
	 * <p><b>Setter dengan efek samping I/O.</b> Nilai {@code null}/kosong DIABAIKAN sepenuhnya
	 * (field tidak berubah, berkas tidak ditulis) &mdash; artinya id sidik jari tidak bisa dikosongkan
	 * lewat jalur ini; melepas kaitan sidik jari harus dilakukan langsung di basis data.</p>
	 *
	 * @param idfinger id sidik jari; {@code null}/kosong = no-op
	 */
	public void setIdfinger(String idfinger) {
		if (idfinger != null && !idfinger.trim().isEmpty()) {
			put(idfinger.trim(), "idfinger");
			this.idfinger = idfinger;
		}
	}

	/**
	 * Berkas keluarga ({@link OrangTua}) tempat siswa ini terdaftar sebagai anak &mdash; <b>penunjuk
	 * ARAH ANAK &rarr; INDUK dari relasi orang tua-anak</b>.
	 *
	 * <h4>Bagaimana relasi orang tua-anak sesungguhnya dibentuk</h4>
	 * <p>Relasi disimpan DUA KALI, dan hanya satu arah yang berupa foreign key sungguhan:</p>
	 * <ul>
	 *   <li><b>Arah anak &rarr; induk (di sini)</b>: kolom {@code sekolah.siswa.orang_tua}, foreign key
	 *   biasa ke {@code public.orang_tua}. Inilah satu-satunya sisi yang dijamin integritasnya oleh
	 *   basis data.</li>
	 *   <li><b>Arah induk &rarr; anak</b>: kolom teks {@code orang_tua.anak} berisi satu JSON datar
	 *   {@code {"siswa_1201":1201,"mahasiswa_88014":88014}} &mdash; BUKAN tabel relasi, BUKAN foreign
	 *   key. {@link OrangTua#ambilAnakSiswa()} sekadar mengurai JSON itu dan mengumpulkan nilai untuk
	 *   setiap kunci berawalan {@code "siswa"}.</li>
	 * </ul>
	 * <p><b>Konsekuensi yang penting untuk keamanan.</b> {@link OrangTua#ambilAnakSiswa()} bukan
	 * utilitas tampilan melainkan <i>penentu ruang lingkup akses data</i> portal wali murid: puluhan
	 * layar menyaring dengan {@code Restrictions.in("siswa.id", ...ambilAnakSiswa())}. Karena method
	 * itu menelan kegagalan penguraian JSON dan mengembalikan daftar KOSONG, sedangkan banyak
	 * pemanggil memperlakukan daftar kosong sebagai "tanpa pembatas" alih-alih "tidak ada anak", pola
	 * fail-open yang sudah dikonfirmasi berulang kali sepanjang audit ini berakar tepat di bentuk
	 * penyimpanan tersebut. Kolom {@code orang_tua} di kelas inilah satu-satunya sisi yang bisa
	 * dipercaya bila kelak pembatas itu diperbaiki.</p>
	 * <p>Kedua arah TIDAK disinkronkan oleh kode mana pun di entity ini: mengisi kolom {@code orang_tua}
	 * di sini tidak menambahkan kunci {@code "siswa_<id>"} ke JSON induk, dan sebaliknya. Menghapus
	 * baris siswa juga meninggalkan id yatim di JSON induk.</p>
	 *
	 * <p>Perhatikan pula bahwa data ayah/ibu/wali ADA DI DUA TEMPAT: trio lengkap milik entity ini
	 * (lihat {@link #getNamaAyah()}, {@link #getNikAyah()}, {@link #getHp1ayah()}, dan seterusnya) dan
	 * berkas keluarga {@link OrangTua}. Keduanya tidak pernah disinkronkan, persis seperti pasangan
	 * {@code BiodataMahasiswa}/{@link OrangTua} di modul perguruan tinggi.</p>
	 *
	 * @return berkas keluarga siswa setelah diresolusi {@code check()}, atau {@code null} bila siswa
	 *         belum ditautkan ke berkas keluarga mana pun
	 * @see OrangTua#ambilAnakSiswa()
	 */
	@ManyToOne(cascade = { CascadeType.PERSIST, CascadeType.MERGE }, fetch = FetchType.LAZY)
	@JoinColumn(name = "orang_tua", nullable = true)
	public OrangTua getOrangTua() {
		orangTua = check(orangTua);
		return orangTua;
	}

	/**
	 * Tautkan siswa ke satu berkas keluarga {@link OrangTua}.
	 *
	 * <p>TIDAK menulis balik kunci {@code "siswa_<id>"} ke kolom JSON {@code anak} milik berkas
	 * keluarga; sisi itu hanya dikelola oleh {@code OrangTuaAction}. Menyetel di sini saja membuat
	 * kedua arah relasi tidak konsisten &mdash; siswa "punya" orang tua, tetapi orang tua tidak
	 * "punya" siswa, sehingga portal wali tetap tidak melihat anak ini.</p>
	 *
	 * @param orangTua berkas keluarga; boleh {@code null} untuk melepas tautan
	 */
	public void setOrangTua(OrangTua orangTua) {
		this.orangTua = orangTua;
	}

	/**
	 * Bentuk tautan "login lewat tautan" (magic link) yang membuka sesi siswa ini tanpa
	 * memasukkan kata sandi.
	 *
	 * <p>Hasilnya {@code <host>/m?q=<DES(<id>-Minisiswa-abcdefghijklmnopqrstuvwxyz)>}, di-URL-encode.
	 * Bila konfigurasi {@code login_via_link_menggunakan_domain_masing_masing} aktif, host diambil
	 * dari {@code Sekolah.domain} alih-alih host request. Dipakai {@code SiswaAction},
	 * {@code OrangTuaAction}, {@code PengumumanAkademisAction}, dan {@code TampilanPengumumanAkademisAction}
	 * untuk menyisipkan tautan siap-klik ke surel/pesan pengumuman.</p>
	 *
	 * <p><b>PERINGATAN KEAMANAN &mdash; tautan ini dapat dibuat sendiri oleh penyerang.</b> Seluruh
	 * komponen rahasianya diketahui publik dari kode sumber:</p>
	 * <ul>
	 *   <li>algoritmanya DES dengan passphrase TETAP yang tertanam di kode dan sama untuk seluruh
	 *   instalasi (lihat peringatan pada {@code ais.common.Common#DES_PASS_PHRASE});</li>
	 *   <li>plaintext-nya sepenuhnya deterministik: id siswa (berurutan, mudah ditebak) ditambah
	 *   literal tetap {@code "-Minisiswa-abcdefghijklmnopqrstuvwxyz"};</li>
	 *   <li>tidak ada nonce, tidak ada masa berlaku, tidak ada penanda sekali-pakai, dan tidak ada
	 *   pengikatan ke alamat surel/nomor tujuan &mdash; tautan yang sama berlaku selamanya.</li>
	 * </ul>
	 * <p>Servlet penerimanya, {@code ais.action.servlet.MServet} yang dipetakan ke {@code /m},
	 * tercakup aturan tangkap-semua {@code <intercept-url pattern="/**"
	 * access="IS_AUTHENTICATED_ANONYMOUSLY">} pada {@code applicationContext-security.xml}, jadi
	 * dapat dipanggil TANPA login. Servlet itu mendekripsi {@code q}, memungut
	 * {@link #getPass()} + {@link #getNim()} siswa yang bersangkutan, lalu memanggil
	 * {@code SecurityFilter.doAutoLogin(...)}. Artinya siapa pun yang bisa menghitung ciphertext untuk
	 * sebuah id &mdash; yakni siapa pun yang membaca kode ini &mdash; dapat masuk sebagai siswa mana
	 * pun di instalasi mana pun, lalu menelusuri id 1..N untuk mengambil alih seluruh akun siswa.</p>
	 * <p>Perilaku kode TIDAK diubah di sini; ini catatan dokumentasi.</p>
	 *
	 * @return URL absolut magic-link untuk siswa ini
	 * @throws Exception bila enkripsi atau {@code URLEncoder} gagal, atau bila
	 *          {@link #getSekolah()} {@code null} saat mode domain per-sekolah aktif
	 * @see #getPass()
	 */
	public String urlLogin() throws Exception {
		String url = Common.getRequestHostWithProtocol();

		if (Common.bolehKonfigurasi("login_via_link_menggunakan_domain_masing_masing", Konfigurasi.TIDAK_AKTIF)) {
			HttpServletRequest request = null;
			if (ExecutionsCtrl.getCurrent() != null) {
				request = (HttpServletRequest) ExecutionsCtrl.getCurrent().getNativeRequest();
			}

			if (request == null) {
				request = RequestContext.get();
			}
			url = "https://" + getSekolah().getDomain() + request.getContextPath();
		}

		String code = url + "/m?q=" + URLEncoder
				.encode(Common.desEncrypter.get().encrypt(getId() + "-Minisiswa-abcdefghijklmnopqrstuvwxyz"), "UTF-8");
		return code;
	}

	/**
	 * Nama siswa dalam aksara Arab, dengan {@link #getNama()} sebagai nilai pengganti bila belum diisi.
	 *
	 * <p><b>Perhatikan: fallback ini ikut tersimpan.</b> Entity memakai <i>property access</i>, jadi
	 * Hibernate menulis apa yang DIKEMBALIKAN getter, bukan isi field. Karena field {@code namaAr}
	 * tidak ikut diubah tetapi nilai baliknya sudah berupa nama latin, kolom {@code namaAr} akan terisi
	 * nama latin pada flush berikutnya &mdash; "belum diisi" berubah permanen menjadi "sama dengan nama
	 * latin", dan sesudah itu tidak ada lagi cara membedakan keduanya.</p>
	 *
	 * @return nama Arab bila ada, selain itu nama latin siswa
	 */
	public String getNamaAr() {
		return namaAr == null ? getNama() : namaAr;
	}

