	/**
	 * CSV id {@link KelasLesSiswa} yang dipilih siswa, dinormalkan ke bentuk
	 * {@code ",<id>,<id>,"}.
	 *
	 * <p>Implementasi abstrak {@link VOSiswa#getKelasLesDipilih()}; dipakai
	 * {@link VOSiswa#ambilKelasLesSiswaId()}/{@link VOSiswa#ambilKelasLesSiswa()} untuk memuat
	 * objek kelas les yang sesungguhnya.</p>
	 *
	 * <p><b>Getter dengan dua efek samping.</b> (1) Bila field masih {@code null}, nilainya diambil
	 * dari {@link CalonSiswa#ambilKelasLesDipilih()} milik pendaftaran PSB asal &mdash; jadi membaca
	 * properti ini dapat MENYALIN pilihan kelas les dari data PPDB ke baris siswa secara permanen
	 * (property access: nilai balik ditulis ke kolom pada flush berikutnya). (2) Normalisasi koma
	 * ganda dilakukan dengan tiga kali {@code replaceAll(",,", ",")} berturut-turut &mdash; cukup
	 * untuk kasus lazim, tetapi rentetan koma yang lebih panjang tidak sepenuhnya ternormalkan.</p>
	 *
	 * @return CSV ternormalkan, atau {@code ""} bila tidak ada pilihan; tidak pernah {@code null}
	 */
	public String getKelasLesDipilih() {

		if (kelasLesDipilih == null) {
			CalonSiswa calonSiswa = ambilCalonSiswa();
			if (calonSiswa != null) {
				kelasLesDipilih = calonSiswa.ambilKelasLesDipilih();
			}
		}

		kelasLesDipilih = (kelasLesDipilih == null || kelasLesDipilih.trim().equalsIgnoreCase(",") ? ""
				: "," + kelasLesDipilih.trim() + ",").replaceAll(",,", ",").replaceAll(",,", ",").replaceAll(",,", ",");

		if (kelasLesDipilih.equals(",")) {
			kelasLesDipilih = "";
		} else if (kelasLesDipilih.equals(",,")) {
			kelasLesDipilih = "";
		} else if (kelasLesDipilih.equals(",,,")) {
			kelasLesDipilih = "";
		}
		return kelasLesDipilih == null ? "" : kelasLesDipilih.trim();
	}

