	/**
	 * Paket/jalur PPDB ({@link PaketPsb}) siswa, dengan data pendaftaran sebagai cadangan.
	 *
	 * <p><b>Getter yang mendenormalisasi.</b> Bila kolom {@code paket_psb} masih kosong, nilainya
	 * diambil dari {@link CalonSiswa#getPaketPsb()} milik pendaftaran asal &mdash; dan karena property
	 * access, nilai itu IKUT TERTULIS ke kolom pada flush berikutnya. Sesudah itu paket siswa tidak
	 * lagi mengikuti perubahan di sisi PPDB. Berbeda dari
	 * {@link #getGelombangPendaftaranPsb()}/{@link #getPenjurusanSekolah()}, cadangan di sini TIDAK
	 * dibungkus {@code try}/{@code catch}: kegagalan resolusi {@link CalonSiswa} akan lolos ke
	 * pemanggil, dan bila terjadi saat flush dapat menggagalkan seluruh penyimpanan.</p>
	 *
	 * @return paket PSB siswa, cadangan dari pendaftaran, atau {@code null}
	 */
	@ManyToOne(cascade = { CascadeType.PERSIST, CascadeType.MERGE }, fetch = FetchType.LAZY)
	@JoinColumn(name = "paket_psb")
	public PaketPsb getPaketPsb() {
		paketPsb = check(paketPsb);

		if (paketPsb == null) {
			CalonSiswa calonSiswa = ambilCalonSiswa();
			if (calonSiswa != null) {
				paketPsb = calonSiswa.getPaketPsb();
			}
		}

		return paketPsb;
	}

	/**
	 * Setel paket/jalur PPDB siswa.
	 *
	 * @param paketPsb paket PSB; boleh {@code null}
	 */
	public void setPaketPsb(PaketPsb paketPsb) {
		this.paketPsb = paketPsb;
	}

	/**
	 * Jadwalkan penyegaran keempat kolom riwayat pembayaran siswa ini di latar belakang.
	 *
	 * <p>Membuat {@link Thread} MENTAH (bukan pool), tidur 100 ms, lalu memanggil
	 * {@link #populate(Siswa)}. Dipanggil dari alur yang mengubah tagihan/pembayaran agar layar
	 * pembayaran daring melihat data terbaru tanpa menunggu.</p>
	 *
	 * <p><b>Catatan operasional.</b> Karena thread tidak dikelola: (1) jumlahnya tidak dibatasi &mdash;
	 * penyimpanan massal dapat melahirkan ratusan thread sekaligus; (2) thread membawa entity
	 * {@code Siswa} yang mungkin sudah <i>detached</i> dari sesi pemanggil, sehingga
	 * {@link #populate(Siswa)} harus {@code refresh} sendiri; (3) tidak ada pengurutan &mdash; dua
	 * penyegaran untuk siswa yang sama dapat berjalan bersamaan dan saling menimpa hasil; (4) galat
	 * hanya tercetak ke log, pemanggil tidak pernah tahu penyegaran gagal.</p>
	 */
	public void populatePembayaran() {
		new Thread(new Runnable() {

			@Override
			public void run() {
				try {
					Thread.sleep(100);
				} catch (Exception e) {
					e.printStackTrace(); ais.common.ErrorAuditUtil.record(e, "auto-audit src/ais/database/model/sekolah/Siswa.java:2645");
				}

				Siswa siswa = Siswa.this;
				Siswa.populate(siswa);
			}
		}).start();
	}

	/**
	 * Hitung ulang dan simpan keempat kolom riwayat pembayaran milik satu siswa.
	 *
	 * <p>Dua sumber digabung: (a) seluruh {@code PembayaranSiswaDetail} yang bertaut ke
	 * {@link Tagihan}, dan (b) seluruh {@link Tagihan} milik siswa yang sudah lewat batas
	 * {@code pembayaranBerakhirPada} atau belum punya baris pembayaran, DAN bertanda "bukan tagihan"
	 * atau bernominal &lt; 0,1. Hasilnya empat CSV yang ditulis lewat setter lalu disimpan dengan
	 * {@code Common.refreshUpdate} di dalam transaksi eksplisit.</p>
	 *
	 * <p><b>Mengapa ada {@code session.clear()} di tengah.</b> Komentar di kode menjelaskan bahwa
	 * entity {@link Tagihan} yang ikut termuat dapat menjadi "kotor" karena kode uniknya dihitung ulang
	 * saat dibaca; membiarkannya di sesi membuat flush mencoba meng-{@code UPDATE} tagihan dengan kode
	 * unik duplikat. Sesi karena itu dikosongkan, lalu siswa di-{@code refresh} kembali sebelum
	 * disimpan. Ini konfirmasi langsung dari sisi pemanggil atas perilaku getter destruktif di
	 * {@link Tagihan} yang sudah didokumentasikan di sana.</p>
	 *
	 * <p><b>Titik pecah yang perlu diketahui.</b> Kedua perulangan memanggil
	 * {@code tagihan.getPengaturanBiaya().getJenisBiayaSekolah().getPeriode()} tanpa penjagaan
	 * {@code null} (sementara baris di atasnya justru sudah menyiapkan nilai cadangan {@code -1L}),
	 * sehingga tagihan yang pengaturan biayanya sudah dihapus akan melempar
	 * {@code NullPointerException}. Galatnya ditelan {@code catch} terluar, jadi gejalanya bukan
	 * pesan galat melainkan riwayat yang diam-diam tidak pernah diperbarui.</p>
	 *
	 * <p>Method ini juga menutup sesi ({@code disconnect}+{@code close}+
	 * {@code HibernateUtil.closeSession()}); aman karena hanya dipanggil dari thread latar
	 * {@link #populatePembayaran()}, TIDAK aman bila dipanggil langsung dari thread request.</p>
	 *
	 * @param siswa siswa yang riwayatnya dihitung ulang; diabaikan bila belum punya id
	 */
	@SuppressWarnings("unchecked")
	public static void populate(Siswa siswa) {

		if (siswa.getId() != null) {

			String riwayatPengaturanPembayaran = "";
			String riwayatJenisPembayaran = "";
			String riwayatPembayaran = "";
			String riwayatTagihan = "";

			try {
				Session session = HibernateUtil.currentNativeSession();
				session.refresh(siswa);
				List<PembayaranSiswaDetail> riwayatPembayarans = session.createCriteria(PembayaranSiswaDetail.class)
						.createAlias("pembayaranSiswa", "pembayaranSiswa").add(Restrictions.isNotNull("tagihan"))
						.add(Restrictions.eq("pembayaranSiswa.siswa", siswa)).addOrder(Order.asc("id")).list();

				for (PembayaranSiswaDetail r : riwayatPembayarans) {
					Tagihan tagihan = r.getTagihan();

					if (tagihan.getPembayaranSiswaDetail() != null) {
						Long pemId = r.getId();
						Long jenisId = tagihan.getPengaturanBiaya() != null
								&& tagihan.getPengaturanBiaya().getJenisBiayaSekolah() != null
										? tagihan.getPengaturanBiaya().getJenisBiayaSekolah().getId()
										: -1L;
						Long pengId = tagihan.getPengaturanBiaya() != null ? tagihan.getPengaturanBiaya().getId() : -1L;

						if (tagihan.getPengaturanBiaya().getJenisBiayaSekolah().getPeriode().equals("Bulanan")) {
							riwayatPengaturanPembayaran += riwayatPengaturanPembayaran.isEmpty()
									? (pengId + "_" + tagihan.getBulan() + "_" + tagihan.getTahun())
									: "," + (pengId + "_" + tagihan.getBulan() + "_" + tagihan.getTahun());
						} else {
							riwayatPengaturanPembayaran += riwayatPengaturanPembayaran.isEmpty() ? pengId.toString()
									: "," + pengId;
						}

						riwayatJenisPembayaran += riwayatJenisPembayaran.isEmpty() ? jenisId.toString() : "," + jenisId;

						riwayatPembayaran += riwayatPembayaran.isEmpty() ? pemId.toString() : "," + pemId;

						riwayatTagihan += riwayatTagihan.isEmpty() ? tagihan.getId().toString() : "," + tagihan.getId();
					}

				}
				riwayatPembayarans.clear();
				riwayatPembayarans = null;

				List<Tagihan> tagihans = session.createCriteria(Tagihan.class)

						.add(Restrictions.or(
								Restrictions.and(Restrictions.isNotNull("pembayaranBerakhirPada"),
										Restrictions
												.sqlRestriction("this_.pembayaran_berakhir_pada < CURRENT_TIMESTAMP")),
								Restrictions.isNull("pembayaranSiswaDetail")))

						.add(Restrictions.or(Restrictions.eq("bukanTagihan", true), Restrictions.lt("nominal", 0.1)))
						.add(Restrictions.eq("siswa", siswa)).addOrder(Order.asc("id")).list();

				for (Tagihan tagihan : tagihans) {
					if ((tagihan.getNominal() < 0.1 || tagihan.ambilBukanTagihanData()) && ((tagihan.getAktif() &&  !tagihan.ambilBukanTagihanData()) && !tagihan.getNominalBiaya().getBukanTagihan())) {
//						Long jenisId = tagihan.getPengaturanBiaya() != null
//								&& tagihan.getPengaturanBiaya().getJenisBiayaSekolah() != null
//										? tagihan.getPengaturanBiaya().getJenisBiayaSekolah().getId()
//										: -1L;
						Long pengId = tagihan.getPengaturanBiaya() != null ? tagihan.getPengaturanBiaya().getId() : -1L;

						if (tagihan.getPengaturanBiaya().getJenisBiayaSekolah().getPeriode().equals("Bulanan")) {
							riwayatPengaturanPembayaran += riwayatPengaturanPembayaran.isEmpty()
									? (pengId + "_" + tagihan.getBulan() + "_" + tagihan.getTahun())
									: "," + (pengId + "_" + tagihan.getBulan() + "_" + tagihan.getTahun());
						} else {
							riwayatPengaturanPembayaran += riwayatPengaturanPembayaran.isEmpty() ? pengId.toString()
									: "," + pengId;
						}

//						riwayatJenisPembayaran += riwayatJenisPembayaran.isEmpty() ? jenisId.toString() : "," + jenisId;

						riwayatTagihan += riwayatTagihan.isEmpty() ? tagihan.getId().toString() : "," + tagihan.getId();
					}
				}
				tagihans.clear();
				tagihans = null;

				// Evict semua entitas dari session (termasuk Tagihan yang mungkin
				// kotor/computed kodeUnik) sebelum update Siswa, agar session.flush
				// tidak mencoba UPDATE Tagihan dengan kodeUnik duplikat.
				try { session.clear(); } catch (Exception ignored) { ais.common.ErrorAuditUtil.record(ignored, "auto-audit(empty-catch) src/ais/database/model/sekolah/Siswa.java:2741");}
				// Re-attach siswa ke session setelah clear.
				try { session.refresh(siswa); } catch (Exception ignored) { ais.common.ErrorAuditUtil.record(ignored, "auto-audit(empty-catch) src/ais/database/model/sekolah/Siswa.java:2743");}

				siswa.setRiwayatPengaturanPembayaran(riwayatPengaturanPembayaran);
				siswa.setRiwayatJenisPembayaran(riwayatJenisPembayaran);
				siswa.setRiwayatPembayaran(riwayatPembayaran);
				siswa.setRiwayatTagihan(riwayatTagihan);

				session.getTransaction().begin();
				Common.refreshUpdate(session, siswa);
				session.getTransaction().commit();

				// session.disconnect();
				if (session.isOpen()) {session.disconnect();session.close();}

			} catch (Exception e) {
				e.printStackTrace(); ais.common.ErrorAuditUtil.record(e, "auto-audit src/ais/database/model/sekolah/Siswa.java:2758");
			}

			HibernateUtil.closeSession();

		}
	}

	/**
	 * Kumpulkan SEMUA nomor telepon yang terkait siswa ini dalam satu himpunan unik.
	 *
	 * <p>Sumbernya dua belas properti: telepon siswa, hp1-3 ayah, hp1-3 ibu, hp1-3 wali, telepon orang
	 * tua, dan telepon wali. Dipakai jalur pengumuman/WhatsApp untuk menentukan nomor tujuan.</p>
	 *
	 * <p><b>Bug yang terlihat jelas di kode.</b> Dua pemeriksaan terakhir memakai {@code ||}
	 * (seharusnya {@code &&}): {@code x != null || !x.trim().isEmpty()}. Karena getter telepon orang
	 * tua/wali tidak pernah mengembalikan {@code null}, ekspresi itu SELALU benar, sehingga nilai
	 * {@code ""} ikut dimasukkan ke himpunan. Pemanggil yang tidak menyaring string kosong akan
	 * mencoba mengirim pesan ke nomor kosong.</p>
	 *
	 * <p>Perhatikan juga {@link #getTeleponOrangTua()} bersifat destruktif (lihat Javadoc-nya):
	 * memanggil method ini pada instance yang masih terhubung sesi dapat menimpa kolom
	 * {@code telepon_orang_tua}.</p>
	 *
	 * @return himpunan nomor telepon; kosong bila tidak ada satu pun terisi
	 */
	public Set<String> ambilTelp() {
		Set<String> froms = new HashSet<String>();
		Siswa calonSiswa = this;
		if (calonSiswa.getTeleponSiswa() != null && !calonSiswa.getTeleponSiswa().trim().isEmpty()) {
			froms.add(calonSiswa.getTeleponSiswa().trim());
		}

		if (calonSiswa.getHp1ayah() != null && !calonSiswa.getHp1ayah().trim().isEmpty()) {
			froms.add(calonSiswa.getHp1ayah().trim());
		}

		if (calonSiswa.getHp2ayah() != null && !calonSiswa.getHp2ayah().trim().isEmpty()) {
			froms.add(calonSiswa.getHp2ayah().trim());
		}

		if (calonSiswa.getHp3ayah() != null && !calonSiswa.getHp3ayah().trim().isEmpty()) {
			froms.add(calonSiswa.getHp3ayah().trim());
		}

		if (calonSiswa.getHp1ibu() != null && !calonSiswa.getHp1ibu().trim().isEmpty()) {
			froms.add(calonSiswa.getHp1ibu().trim());
		}

		if (calonSiswa.getHp2ibu() != null && !calonSiswa.getHp2ibu().trim().isEmpty()) {
			froms.add(calonSiswa.getHp2ibu().trim());
		}

		if (calonSiswa.getHp3ibu() != null && !calonSiswa.getHp3ibu().trim().isEmpty()) {
			froms.add(calonSiswa.getHp3ibu().trim());
		}

		if (calonSiswa.getHp1wali() != null && !calonSiswa.getHp1wali().trim().isEmpty()) {
			froms.add(calonSiswa.getHp1wali().trim());
		}

		if (calonSiswa.getHp2wali() != null && !calonSiswa.getHp2wali().trim().isEmpty()) {
			froms.add(calonSiswa.getHp2wali().trim());
		}

		if (calonSiswa.getHp3wali() != null && !calonSiswa.getHp3wali().trim().isEmpty()) {
			froms.add(calonSiswa.getHp3wali().trim());
		}

		if (calonSiswa.getTeleponOrangTua() != null || !calonSiswa.getTeleponOrangTua().trim().isEmpty()) {
			froms.add(calonSiswa.getTeleponOrangTua().trim());
		}

		if (calonSiswa.getTeleponWali() != null || !calonSiswa.getTeleponWali().trim().isEmpty()) {
			froms.add(calonSiswa.getTeleponWali().trim());
		}
		return froms;
	}

	/**
	 * Waktu terakhir kata sandi siswa diubah; dibaca layar keamanan untuk memaksa penggantian berkala.
	 */
	private Date ubahPasword;

	/**
	 * Waktu terakhir kata sandi siswa diubah.
	 *
	 * <p>Bernilai {@code null} untuk siswa yang kata sandinya tidak pernah diganti &mdash; termasuk
	 * seluruh siswa yang kata sandinya dibangkitkan otomatis oleh {@link #getPass()} dari NISN, yang
	 * merupakan mayoritas baris pada instalasi baru.</p>
	 *
	 * @return waktu penggantian terakhir, atau {@code null}
	 */
	@Temporal(TemporalType.TIMESTAMP)
	public Date getUbahPasword() {
		return ubahPasword;
	}

	/**
	 * Setel waktu penggantian kata sandi terakhir.
	 *
	 * @param ubahPasword waktu penggantian; boleh {@code null}
	 */
	public void setUbahPasword(Date ubahPasword) {
		this.ubahPasword = ubahPasword;
	}

	/**
	 * Nomor seri blangko transkrip nilai siswa (dokumen resmi bernomor, dicetak di rapor/transkrip
	 * kelulusan). Pasangan {@link #getNoSeriIjazah()}.
	 *
	 * @return nomor seri transkrip apa adanya; boleh {@code null}
	 */
	public String getNoSeriTranskrip() {
		return noSeriTranskrip;
	}

	/**
	 * Setel nomor seri blangko transkrip.
	 *
	 * @param noSeriTranskrip nomor seri; boleh {@code null}
	 */
	public void setNoSeriTranskrip(String noSeriTranskrip) {
		this.noSeriTranskrip = noSeriTranskrip;
	}

	/**
	 * Tanggal kelulusan siswa (presisi tanggal).
	 *
	 * <p>Berbeda dari {@link #getTahunLulus()} yang memasang syarat tambahan: tanggal ini
	 * dikembalikan apa adanya walau {@link #getStatusKeluar()} masih kosong, sehingga sepasang siswa
	 * bisa punya tanggal lulus terisi tetapi tahun lulus {@code null}.</p>
	 *
	 * @return tanggal lulus, atau {@code null} bila belum lulus/belum diisi
	 */
	@Temporal(TemporalType.DATE)
	public Date getTanggalLulus() {
		return tanggalLulus;
	}

	/**
	 * Setel tanggal kelulusan siswa.
	 *
	 * @param tanggalLulus tanggal lulus; boleh {@code null}
	 */
	public void setTanggalLulus(Date tanggalLulus) {
		this.tanggalLulus = tanggalLulus;
	}

	/**
	 * Alias BACA-SAJA atas kolom {@code nomor_induk} (NIS).
	 *
	 * <p>Dipetakan {@code insertable = false, updatable = false}, jadi tidak pernah ikut ditulis
	 * walau nilainya berbeda dari {@link #getNomorInduk()}. Kembar pola {@link #getNama()} (alias
	 * {@code nama_siswa}) dan {@link #getNim()} (alias {@code nomor_induk_nasional}): ketiganya ada
	 * semata agar kode generik yang mengharapkan nama properti gaya perguruan tinggi tetap jalan pada
	 * entity siswa.</p>
	 *
	 * <p><b>Jebakan.</b> Field {@code nis} hanya terisi saat entity dimuat Hibernate. Pada objek yang
	 * dibuat lewat {@code new Siswa(...)} atau dimuat lewat proyeksi tertentu, getter ini
	 * mengembalikan {@code null} walaupun {@link #getNomorInduk()} berisi nilai.</p>
	 *
	 * @return NIS hasil pemuatan Hibernate, atau {@code null}
	 */
	@Column(name = "nomor_induk", nullable = false, insertable = false, updatable = false)
	public String getNis() {
		return nis;
	}

	/**
	 * Setel field alias NIS. Tidak berpengaruh ke basis data (kolom dipetakan baca-saja).
	 *
	 * @param nis nilai alias; boleh {@code null}
	 */
	public void setNis(String nis) {
		this.nis = nis;
	}

	/**
	 * Kelas berjalan siswa &mdash; alias {@code @Transient} untuk {@link #getKelas()}.
	 *
	 * <p>Ada untuk memenuhi kontrak kode generik yang memakai nama properti {@code currentKelas}.
	 * Seluruh perilaku (termasuk efek samping berat dan risiko menimpa {@code current_kelas_id})
	 * sepenuhnya milik {@link #getKelas()}; baca Javadoc di sana sebelum memakainya.</p>
	 *
	 * @return hasil {@link #getKelas()}
	 */
	@Transient
	public KelasSiswa getCurrentKelas() {
		// TODO Auto-generated method stub
		return getKelas();
	}
